-- ============================================================================
-- 3. Mint new ids (66 tables)
-- ============================================================================

-- One INSERT per table. uuidv7(interval) shifts the clock by the interval, so
-- uuidv7(t - clock_timestamp()) embeds time t. Prisma's timestamp(3) columns
-- hold UTC without a zone; AT TIME ZONE 'UTC' reads them as such whatever the
-- session TimeZone is. Rows are minted in creation order, ties by old id.

-- Agreement: time from no creation-time column, so plain uuidv7() in old-id order
INSERT INTO "_id_map" (table_name, old_id, new_id)
SELECT 'Agreement', id, uuidv7()
FROM "Agreement" ORDER BY id;

-- Boundary: time from "createdAt"
INSERT INTO "_id_map" (table_name, old_id, new_id)
SELECT 'Boundary', id, uuidv7(("createdAt" AT TIME ZONE 'UTC') - clock_timestamp())
FROM "Boundary" ORDER BY "createdAt", id;

-- BrainActivity: time from "createdAt"
INSERT INTO "_id_map" (table_name, old_id, new_id)
SELECT 'BrainActivity', id, uuidv7(("createdAt" AT TIME ZONE 'UTC') - clock_timestamp())
FROM "BrainActivity" ORDER BY "createdAt", id;

