-- Report, without failing, any unconstrained value that matched no id.
DO $$
DECLARE
  r record;
  n bigint;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('ConsentRecord', 'targetId'),
    ('GratitudeEntry', 'linkedConflictId'),
    ('MeditationSession', 'linkedConflictId'),
    ('Message', 'forUserId'),
    ('PersonMention', 'sourceId'),
    ('PersonMention', 'userId'),
    ('PreSessionMessage', 'associatedSessionId'),
    ('PreSessionMessage', 'userId'),
    ('ReconcilerResult', 'guesserId'),
    ('ReconcilerResult', 'subjectId'),
    ('ReconcilerShareOffer', 'userId'),
    ('SavedMeditation', 'conversationId'),
    ('Stage4Closure', 'closedByUserId'),
    ('Stage4NeedCoverage', 'needId'),
    ('Stage4NeedCoverage', 'sourceUserId'),
    ('Stage4NeedDeclination', 'needId'),
    ('Stage4NeedDeclination', 'userId'),
    ('Stage4ProposalRevision', 'actorUserId'),
    ('Stage4ProposalRevision', 'messageId'),
    ('Stage4ProposalRevision', 'sessionId'),
    ('Stage4SubChat', 'anchorId'),
    ('StrategyProposal', 'capturedFromMessageId'),
    ('StrategyProposal', 'parentProposalId'),
    ('TendingEntry', 'ownerUserId'),
    ('TendingNeedOutcome', 'needId'),
    ('TendingNeedOutcome', 'sourceUserId')
  ) AS v(t, c) LOOP
    EXECUTE format(
      'SELECT count(*) FROM %I WHERE %I IS NOT NULL AND %I !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$''',
      r.t, r.c, r.c) INTO n;
    IF n > 0 THEN
      RAISE NOTICE 'cuid_to_uuidv7: %.% kept % value(s) that are not ids of any row', r.t, r.c, n;
    END IF;
  END LOOP;
END $$;

-- Embedded ids (4). Every cuid-shaped token that is an old id is replaced.

-- RefinementAttemptCounter.direction: `${guesserId}->${subjectId}`, rebuilt as a lookup key (services/reconciler/circuit-breaker.ts:23, 46)
UPDATE "RefinementAttemptCounter" SET "direction" = "_rewrite_embedded_ids"("direction")
WHERE "direction" ~ 'c[a-z0-9]{24}';

-- TendingCoordinationCycle.resultSummary: "Missing participant(s): <userIds>" on timeout (services/tending.service.ts:1622)
UPDATE "TendingCoordinationCycle" SET "resultSummary" = "_rewrite_embedded_ids"("resultSummary")
WHERE "resultSummary" ~ 'c[a-z0-9]{24}';

-- User.clerkId: `e2e_${userId}` from the E2E auth bypass (dev/e2e databases only; production holds Clerk ids)
UPDATE "User" SET "clerkId" = "_rewrite_embedded_ids"("clerkId")
WHERE "clerkId" ~ 'c[a-z0-9]{24}';

-- UserVessel.lastSeenChatItemId: a Message id, or a client chat-item id like `context-shared-${messageId}` (controllers/sessions.ts:1091)
UPDATE "UserVessel" SET "lastSeenChatItemId" = "_rewrite_embedded_ids"("lastSeenChatItemId")
WHERE "lastSeenChatItemId" ~ 'c[a-z0-9]{24}';

-- JSON documents and composite keys (4).

-- StageProgress.gatesSatisfied: stage4Walkthrough.{currentNeedId, coveredNeedIds[], skippedNeedIds[]}, need ids in either space (controllers/stage4.ts:501, services/stream-turn-actions.ts:243). No other gate key holds an id.
UPDATE "StageProgress"
SET "gatesSatisfied" = jsonb_set(
  "gatesSatisfied", '{stage4Walkthrough}',
  "_jsonb_map_keys"("gatesSatisfied" -> 'stage4Walkthrough',
                    ARRAY['currentNeedId', 'coveredNeedIds', 'skippedNeedIds'],
                    ARRAY['IdentifiedNeed', 'Stage4NeedCoverage']))
WHERE jsonb_typeof("gatesSatisfied" -> 'stage4Walkthrough') = 'object';

-- Stage4ProposalRevision.before, after: proposal snapshots: agreementId (Agreement), removedByUserId (User), and needsAddressed, which is need labels but tolerated as ids by its readers, so any element that is a need id is mapped too (controllers/stage4.ts:1429, services/stage4-capture.service.ts:600)
UPDATE "Stage4ProposalRevision"
SET "before" = "_jsonb_map_keys"("_jsonb_map_keys"("_jsonb_map_keys"("before",
                 ARRAY['agreementId'], ARRAY['Agreement']),
                 ARRAY['removedByUserId'], ARRAY['User']),
                 ARRAY['needsAddressed'], ARRAY['IdentifiedNeed', 'Stage4NeedCoverage']),
    "after"  = "_jsonb_map_keys"("_jsonb_map_keys"("_jsonb_map_keys"("after",
                 ARRAY['agreementId'], ARRAY['Agreement']),
                 ARRAY['removedByUserId'], ARRAY['User']),
                 ARRAY['needsAddressed'], ARRAY['IdentifiedNeed', 'Stage4NeedCoverage'])
WHERE jsonb_typeof("before") = 'object' OR jsonb_typeof("after") = 'object';

-- StrategyProposal.needsAddressed: need LABELS (services/stage-tools.ts:100 tells the model "never use internal IDs"); readers also match elements against need ids (services/stage4-coverage.service.ts:156), so an element that is a need id is mapped and every label is kept. Stays text[].
UPDATE "StrategyProposal"
SET "needsAddressed" = ARRAY(
  SELECT "_uuid_text_or_keep"(ARRAY['IdentifiedNeed', 'Stage4NeedCoverage'], e)
  FROM unnest("needsAddressed") WITH ORDINALITY AS u(e, ord) ORDER BY ord)
WHERE "needsAddressed" && (SELECT array_agg(old_id) FROM "_id_map"
                           WHERE table_name IN ('IdentifiedNeed', 'Stage4NeedCoverage'));

-- TendingCoordinationCycle.coordinationKey: `${sessionId}:${[...entryIds].sort().join("|")}`, a lookup key (services/tending.service.ts:40). Rebuilt from its own parts: mapping in place would keep the OLD sort order, and the app re-derives the key with JavaScript sort (UTF-16 code units = COLLATE "C" for hex and "-").
UPDATE "TendingCoordinationCycle"
SET "coordinationKey" =
  "_uuid_text_or_keep"(ARRAY['Session'], split_part("coordinationKey", ':', 1)) || ':' ||
  coalesce((SELECT string_agg(k, '|' ORDER BY k COLLATE "C")
            FROM (SELECT "_uuid_text_or_keep"(ARRAY['TendingEntry'], e) AS k
                  FROM unnest(string_to_array(substr("coordinationKey", strpos("coordinationKey", ':') + 1), '|')) AS e
                  WHERE e <> '') s), '')
WHERE "coordinationKey" LIKE '%:%';


