-- Every id is one this migration minted for that table.
DO $$
DECLARE
  t text;
  n bigint;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'Agreement',
    'Boundary',
    'BrainActivity',
    'CommonGround',
    'ConsentRecord',
    'ConsentedContent',
    'EmotionalExerciseCompletion',
    'EmotionalReading',
    'EmpathyAttempt',
    'EmpathyDraft',
    'EmpathyValidation',
    'GlobalLibraryItem',
    'GratitudeEntry',
    'GratitudePreferences',
    'IdentifiedNeed',
    'InnerWorkMessage',
    'InnerWorkSession',
    'Insight',
    'Invitation',
    'MeditationFavorite',
    'MeditationPreferences',
    'MeditationSession',
    'MeditationStats',
    'Message',
    'NeedScore',
    'NeedsAssessmentState',
    'Person',
    'PersonMention',
    'PreSessionMessage',
    'ReconcilerResult',
    'ReconcilerShareOffer',
    'RecurringTheme',
    'RefinementAttemptCounter',
    'Relationship',
    'RelationshipMember',
    'SavedMeditation',
    'Session',
    'SessionTakeaway',
    'SharedVessel',
    'Stage4Closure',
    'Stage4NeedCoverage',
    'Stage4NeedDeclination',
    'Stage4ProposalRevision',
    'Stage4ProposalSelection',
    'Stage4SubChat',
    'Stage4SubChatMessage',
    'StageProgress',
    'StrategyProposal',
    'StrategyRanking',
    'TakeawayLink',
    'TendingAdjustment',
    'TendingBetweenPeriodNote',
    'TendingCheckin',
    'TendingCoordinationCycle',
    'TendingEntry',
    'TendingEntryOutcome',
    'TendingNeedOutcome',
    'TendingReminder',
    'TendingResponse',
    'TendingResponsePartialClosure',
    'User',
    'UserDocument',
    'UserEvent',
    'UserMemory',
    'UserVessel',
    'ValidationFeedbackDraft'
  ] LOOP
    EXECUTE format(
      'SELECT count(*) FROM %I x WHERE NOT EXISTS (SELECT 1 FROM "_id_map" m WHERE m.table_name = %L AND m.new_id = x.id)',
      t, t) INTO n;
    IF n > 0 THEN
      RAISE EXCEPTION 'cuid_to_uuidv7: % has % id(s) this migration did not mint', t, n;
    END IF;
  END LOOP;
END $$;

